CREATE TABLE habitaciones (id INT PRIMARY KEY COMMENT 'Identificador único', hotel_id INT, numero INT, tarifa DECIMAL(10,2), FOREIGN KEY (hotel_id) REFERENCES hoteles(id)) COMMENT='Dominio hoteleria: habitaciones';
